from __future__ import annotations

import json
import sys
from pathlib import Path


GENERATED_HEADER = """# Generated by experiments/pearson_robot_skeleton_graph/scripts/build_skeleton_graph_rhino.py.
# Do not edit by hand. Edit assembly_graph.json and regenerate.
"""


RUNTIME_CODE = r'''
import json
import math
import System

import Rhino
import rhinoscriptsyntax as rs
import scriptcontext as sc


GRAPH = __ASSEMBLY_GRAPH_JSON__
SOURCE = "pearson_robot_skeleton_graph"


def ensure_layer(layer_path, color=None):
    current_path = ""
    parent_id = System.Guid.Empty
    for name in layer_path.split("::"):
        current_path = name if not current_path else current_path + "::" + name
        layer_index = sc.doc.Layers.FindByFullPath(current_path, True)
        if layer_index >= 0:
            parent_id = sc.doc.Layers[layer_index].Id
            continue
        layer = Rhino.DocObjects.Layer()
        layer.Name = name
        if parent_id != System.Guid.Empty:
            layer.ParentLayerId = parent_id
        if color is not None:
            layer.Color = System.Drawing.Color.FromArgb(color[0], color[1], color[2])
        layer_index = sc.doc.Layers.Add(layer)
        parent_id = sc.doc.Layers[layer_index].Id
    return sc.doc.Layers.FindByFullPath(layer_path, True)


def color_for_side(side):
    if side == "left":
        return [0, 210, 190]
    if side == "right":
        return [235, 95, 170]
    return [255, 214, 80]


def member_side(member, nodes_by_id):
    from_side = nodes_by_id[member["from"]]["side"]
    to_side = nodes_by_id[member["to"]]["side"]
    if from_side == to_side:
        return from_side
    if to_side in ("left", "right"):
        return to_side
    return from_side


def json_string(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def attrs(name, layer_path, color, user_strings):
    attributes = Rhino.DocObjects.ObjectAttributes()
    attributes.Name = name
    attributes.LayerIndex = ensure_layer(layer_path, color)
    attributes.ColorSource = Rhino.DocObjects.ObjectColorSource.ColorFromObject
    attributes.ObjectColor = System.Drawing.Color.FromArgb(color[0], color[1], color[2])
    for key, value in user_strings.items():
        attributes.SetUserString(key, str(value))
    return attributes


def shifted_point(position, offset):
    return Rhino.Geometry.Point3d(
        position[0] + offset[0],
        position[1] + offset[1],
        position[2] + offset[2],
    )


def distance(a, b):
    return math.sqrt(sum((a[index] - b[index]) ** 2 for index in range(3)))


def unit_vector(start, end):
    length = distance(start, end)
    if length <= 0:
        return [0.0, 0.0, 0.0]
    return [(end[index] - start[index]) / length for index in range(3)]


def point_along(start, direction, length):
    return [start[index] + direction[index] * length for index in range(3)]


def lifted_position(position, lift):
    return [position[0], position[1], position[2] + lift]


def clear_previous():
    object_ids = rs.AllObjects()
    if not object_ids:
        return 0
    delete_ids = []
    for object_id in object_ids:
        if rs.GetUserText(object_id, "rook.graph.source") == SOURCE:
            delete_ids.append(object_id)
    if delete_ids:
        rs.DeleteObjects(delete_ids)
    return len(delete_ids)


def add_joint(pose_id, node, position, offset, layer_path, radius, feature_ids, relationship_ids):
    color = color_for_side(node["side"])
    point = shifted_point(position, offset)
    user_strings = {
        "rook.graph.source": SOURCE,
        "rook.graph.kind": "assembly_graph",
        "rook.graph.revision": GRAPH["revision"],
        "rook.graph.visual_type": "joint",
        "rook.graph.pose": pose_id,
        "rook.graph.node_id": node["id"],
        "rook.graph.role": node["role"],
        "rook.graph.side": node["side"],
        "rook.graph.domain_aliases": ",".join(node.get("domain_aliases", [])),
    }
    if feature_ids:
        user_strings["rook.graph.feature_ids"] = json_string(feature_ids)
    if relationship_ids:
        user_strings["rook.graph.relationship_ids"] = json_string(relationship_ids)
    sphere = Rhino.Geometry.Sphere(point, radius).ToBrep()
    object_id = sc.doc.Objects.AddBrep(
        sphere,
        attrs(
            "joint_{}_{}".format(pose_id, node["id"]),
            layer_path,
            color,
            user_strings,
        ),
    )
    return str(object_id)


def add_member(pose_id, member, node_positions, nodes_by_id, offset, layer_path, feature_ids, relationship_ids):
    start = node_positions[member["from"]]
    end = node_positions[member["to"]]
    side = member_side(member, nodes_by_id)
    color = color_for_side(side)
    start_point = shifted_point(start, offset)
    end_point = shifted_point(end, offset)
    line = Rhino.Geometry.LineCurve(start_point, end_point)
    length = distance(start, end)
    user_strings = {
        "rook.graph.source": SOURCE,
        "rook.graph.kind": "assembly_graph",
        "rook.graph.revision": GRAPH["revision"],
        "rook.graph.visual_type": "member",
        "rook.graph.pose": pose_id,
        "rook.graph.member_id": member["id"],
        "rook.graph.from": member["from"],
        "rook.graph.to": member["to"],
        "rook.graph.role": member["role"],
        "rook.graph.member_type": member["member_type"],
        "rook.graph.length_m": round(length, 4),
        "rook.graph.side": side,
        "rook.graph.domain_aliases": ",".join(member.get("domain_aliases", [])),
    }
    if feature_ids:
        user_strings["rook.graph.feature_ids"] = json_string(feature_ids)
    if relationship_ids:
        user_strings["rook.graph.relationship_ids"] = json_string(relationship_ids)
    object_id = sc.doc.Objects.AddCurve(
        line,
        attrs(
            "member_{}_{}".format(pose_id, member["id"]),
            layer_path,
            color,
            user_strings,
        ),
    )
    return str(object_id)


def feature_position(feature, node_positions, members_by_id):
    owner = feature["owner"]
    if feature["owner_kind"] == "node":
        return node_positions[owner]
    member = members_by_id[owner]
    if feature["id"].endswith(".start"):
        return node_positions[member["from"]]
    if feature["id"].endswith(".end"):
        return node_positions[member["to"]]
    raise ValueError("Unsupported member feature id: {}".format(feature["id"]))


def add_feature_marker(pose_id, feature, node_positions, members_by_id, offset, layer_path, radius, visual_lift):
    position = feature_position(feature, node_positions, members_by_id)
    color = [245, 245, 245] if feature["owner_kind"] == "node" else [140, 180, 255]
    point = shifted_point(lifted_position(position, visual_lift), offset)
    sphere = Rhino.Geometry.Sphere(point, radius).ToBrep()
    object_id = sc.doc.Objects.AddBrep(
        sphere,
        attrs(
            "feature_{}_{}".format(pose_id, feature["id"].replace(".", "_")),
            layer_path,
            color,
            {
                "rook.graph.source": SOURCE,
                "rook.graph.kind": "assembly_graph",
                "rook.graph.revision": GRAPH["revision"],
                "rook.graph.visual_type": "feature",
                "rook.graph.pose": pose_id,
                "rook.graph.feature_id": feature["id"],
                "rook.graph.owner": feature["owner"],
                "rook.graph.owner_kind": feature["owner_kind"],
                "rook.graph.feature_kind": feature["kind"],
                "rook.graph.role": feature["role"],
                "rook.graph.true_position_m": json_string(position),
                "rook.graph.visual_lift_m": visual_lift,
            },
        ),
    )
    return str(object_id)


def relationship_tick_points(relationship, features_by_id, node_positions, members_by_id, tick_length):
    from_feature = features_by_id[relationship["from"]]
    to_feature = features_by_id[relationship["to"]]
    start = feature_position(from_feature, node_positions, members_by_id)
    end = feature_position(to_feature, node_positions, members_by_id)
    if distance(start, end) > 0.0001:
        return start, end

    if from_feature["owner_kind"] == "member":
        member = members_by_id[from_feature["owner"]]
        member_start = node_positions[member["from"]]
        member_end = node_positions[member["to"]]
        if from_feature["id"].endswith(".start"):
            direction = unit_vector(member_start, member_end)
        else:
            direction = unit_vector(member_end, member_start)
        return start, point_along(start, direction, tick_length)

    return start, point_along(start, [0.0, 0.0, 1.0], tick_length)


def add_relationship_marker(pose_id, relationship, features_by_id, node_positions, members_by_id, offset, layer_path, tick_length, visual_lift):
    from_feature = features_by_id[relationship["from"]]
    to_feature = features_by_id[relationship["to"]]
    from_feature_position = feature_position(from_feature, node_positions, members_by_id)
    to_feature_position = feature_position(to_feature, node_positions, members_by_id)
    start, end = relationship_tick_points(relationship, features_by_id, node_positions, members_by_id, tick_length)
    start_point = shifted_point(lifted_position(start, visual_lift), offset)
    end_point = shifted_point(lifted_position(end, visual_lift), offset)
    line = Rhino.Geometry.LineCurve(start_point, end_point)
    object_id = sc.doc.Objects.AddCurve(
        line,
        attrs(
            "relationship_{}_{}".format(pose_id, relationship["id"]),
            layer_path,
            [255, 255, 255],
            {
                "rook.graph.source": SOURCE,
                "rook.graph.kind": "assembly_graph",
                "rook.graph.revision": GRAPH["revision"],
                "rook.graph.visual_type": "relationship",
                "rook.graph.pose": pose_id,
                "rook.graph.relationship_id": relationship["id"],
                "rook.graph.relationship_type": relationship["type"],
                "rook.graph.from_feature": relationship["from"],
                "rook.graph.to_feature": relationship["to"],
                "rook.graph.contact_kind": relationship["contact_kind"],
                "rook.graph.provenance": relationship["provenance"],
                "rook.graph.from_feature_position_m": json_string(from_feature_position),
                "rook.graph.to_feature_position_m": json_string(to_feature_position),
                "rook.graph.marker_start_m": json_string(start),
                "rook.graph.marker_end_m": json_string(end),
                "rook.graph.visual_lift_m": visual_lift,
            },
        ),
    )
    return str(object_id)


def set_document_metadata():
    sc.doc.Strings.SetString("rook.project", GRAPH["project"])
    sc.doc.Strings.SetString("rook.units", GRAPH["units"])
    sc.doc.Strings.SetString("rook.graph_experiment", SOURCE)
    sc.doc.Strings.SetString("rook.graph_revision", GRAPH["revision"])
    sc.doc.Strings.SetString("rook.graph_source", r"experiments\pearson_robot_skeleton_graph\assembly_graph.json")
    sc.doc.Strings.SetString("rook.modeling_strategy", "feature_graph_first")


def make_overview_view():
    rs.ViewCameraTarget(None, (-3.0, -7.5, 3.0), (0.0, 0.6, 1.45))
    rs.ViewProjection(None, 2)
    try:
        rs.ViewCameraLens(None, 28.0)
    except Exception:
        pass
    existing = sc.doc.NamedViews.FindByName("skeleton_graph_overview")
    if existing >= 0:
        sc.doc.NamedViews.Delete(existing)
    active_view = sc.doc.Views.ActiveView
    if active_view is not None:
        sc.doc.NamedViews.Add("skeleton_graph_overview", active_view.ActiveViewportID)


def main():
    deleted_count = clear_previous()
    set_document_metadata()
    root_layer = "Pearson Robot Skeleton Graph"
    ensure_layer(root_layer)

    nodes_by_id = {node["id"]: node for node in GRAPH["nodes"]}
    members_by_id = {member["id"]: member for member in GRAPH["members"]}
    features_by_id = {feature["id"]: feature for feature in GRAPH.get("features", [])}
    pose_offsets = GRAPH["visualization"]["pose_offsets"]
    joint_radius = GRAPH["visualization"]["joint_radius"]
    feature_radius = GRAPH["visualization"].get("feature_radius", joint_radius * 0.45)
    tick_length = GRAPH["visualization"].get("relationship_tick_length", joint_radius * 2.0)
    visual_lift = GRAPH["visualization"].get("semantic_visual_lift", 0.0)
    created_joints = []
    created_members = []
    created_features = []
    created_relationships = []

    features_by_owner = {}
    relationships_by_owner = {}
    for feature in GRAPH.get("features", []):
        features_by_owner.setdefault(feature["owner"], []).append(feature["id"])
    for relationship in GRAPH.get("relationships", []):
        for feature_id in (relationship["from"], relationship["to"]):
            feature = features_by_id[feature_id]
            relationships_by_owner.setdefault(feature["owner"], []).append(relationship["id"])

    for pose_id, pose in GRAPH["poses"].items():
        layer_name = "01 Rest T-Pose" if pose_id == "rest_t_pose" else "02 Reclined Pose"
        layer_path = root_layer + "::" + layer_name
        semantic_layer_path = layer_path + "::Feature Relationships"
        offset = pose_offsets[pose_id]
        node_positions = pose["nodes"]
        for node in GRAPH["nodes"]:
            created_joints.append(add_joint(
                pose_id,
                node,
                node_positions[node["id"]],
                offset,
                layer_path,
                joint_radius,
                features_by_owner.get(node["id"], []),
                relationships_by_owner.get(node["id"], []),
            ))
        for member in GRAPH["members"]:
            created_members.append(add_member(
                pose_id,
                member,
                node_positions,
                nodes_by_id,
                offset,
                layer_path,
                features_by_owner.get(member["id"], []),
                relationships_by_owner.get(member["id"], []),
            ))
        for feature in GRAPH.get("features", []):
            created_features.append(add_feature_marker(
                pose_id,
                feature,
                node_positions,
                members_by_id,
                offset,
                semantic_layer_path,
                feature_radius,
                visual_lift,
            ))
        for relationship in GRAPH.get("relationships", []):
            created_relationships.append(add_relationship_marker(
                pose_id,
                relationship,
                features_by_id,
                node_positions,
                members_by_id,
                offset,
                semantic_layer_path,
                tick_length,
                visual_lift,
            ))

    make_overview_view()
    sc.doc.Views.Redraw()
    print(json.dumps({
        "success": True,
        "revision": GRAPH["revision"],
        "deleted_count": deleted_count,
        "pose_count": len(GRAPH["poses"]),
        "joint_count": len(created_joints),
        "member_count": len(created_members),
        "feature_count": len(created_features),
        "relationship_marker_count": len(created_relationships),
        "created_count": len(created_joints) + len(created_members) + len(created_features) + len(created_relationships),
    }, sort_keys=True))


main()
'''


def build_script(graph_path: Path) -> str:
    graph = json.loads(graph_path.read_text(encoding="utf-8"))
    payload = json.dumps(graph, indent=2, sort_keys=True)
    code = RUNTIME_CODE.replace("__ASSEMBLY_GRAPH_JSON__", "json.loads(" + repr(payload) + ")")
    return GENERATED_HEADER + "\n" + code


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print("usage: build_skeleton_graph_rhino.py <assembly_graph.json> <output.py>", file=sys.stderr)
        return 2
    graph_path = Path(argv[1])
    output_path = Path(argv[2])
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(build_script(graph_path), encoding="utf-8")
    print(f"wrote {output_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
